Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp2\src\browse\search.ts", "content": "import type { Artwork } from '../types/artwork'

/** Lower case, with accents removed, so "cezanne" finds "Cézanne". */
export function normalize(value: string): string {
  return value
    .normalize('NFD')
    .replace(/\p{Diacritic}/gu, '')
    .toLowerCase()
    .trim()
}

export function searchWorks(works: Artwork[], query: string): Artwork[] {
  const needle = normalize(query)
  if (!needle) return works
  return works.filter(
    (work) =>
      normalize(work.title ?? '').includes(needle) ||
      normalize(work.artist ?? '').includes(needle),
  )
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp2\src\browse\sort.ts", "content": "import type { Artwork } from '../types/artwork'

export const SORT_KEYS = ['title', 'artist', 'year'] as const
export type SortKey = (typeof SORT_KEYS)[number]

export const SORT_DIRECTIONS = ['asc', 'desc'] as const
export type SortDirection = (typeof SORT_DIRECTIONS)[number]

const collator = new Intl.Collator('en', { sensitivity: 'base', numeric: true })

function compareValues(a: string | number, b: string | number): number {
  if (typeof a === 'number' && typeof b === 'number') return a - b
  return collator.compare(String(a), String(b))
}

/** Sorted copy. Works missing the sort field come last in either direction. */
export function sortWorks(
  works: Artwork[],
  key: SortKey,
  direction: SortDirection,
): Artwork[] {
  const sign = direction === 'asc' ? 1 : -1
  return [...works].sort((a, b) => {
    const left = a[key]
    const right = b[key]
    if (left === null && right === null) return a.id - b.id
    if (left === null) return 1
    if (right === null) return -1
    return sign * compareValues(left, right) || a.id - b.id
  })
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp2\src\browse\filter.ts", "content": "import type { Artwork } from '../types/artwork'

export interface Filters {
  departments: string[]
  types: string[]
}

export function hasActiveFilters(filters: Filters): boolean {
  return filters.departments.length > 0 || filters.types.length > 0
}

function allows(selected: string[], value: string | null): boolean {
  return selected.length === 0 || (value !== null && selected.includes(value))
}

/** Values within a group are alternatives; the two groups must both match. */
export function filterWorks(works: Artwork[], filters: Filters): Artwork[] {
  if (!hasActiveFilters(filters)) return works
  return works.filter(
    (work) =>
      allows(filters.departments, work.department) &&
      allows(filters.types, work.artworkType),
  )
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp2\src\browse\rooms.ts", "content": "import type { Artwork } from '../types/artwork'
import { filterWorks } from './filter'
import type { Filters } from './filter'

export interface Room {
  department: string
  works: Artwork[]
  /** True when filters are active and nothing in this room matches. */
  dimmed: boolean
}

export const OTHER_ROOM = 'Other works'

/**
 * One room per department that holds works, in the given order. Departments
 * not in the list follow, in the order their works appear.
 */
export function buildRooms(
  works: Artwork[],
  departments: string[],
  filters: Filters,
): Room[] {
  const byDepartment = new Map<string, Artwork[]>(
    departments.map((department) => [department, []]),
  )
  for (const work of works) {
    const department = work.department ?? OTHER_ROOM
    const room = byDepartment.get(department)
    if (room) room.push(work)
    else byDepartment.set(department, [work])
  }

  const rooms: Room[] = []
  for (const [department, all] of byDepartment) {
    if (all.length === 0) continue
    const matching = filterWorks(all, filters)
    rooms.push({ department, works: matching, dimmed: matching.length === 0 })
  }
  return rooms
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp2\src\browse\periods.ts", "content": "import type { Artwork } from '../types/artwork'
import { sortWorks } from './sort'

export interface Period {
  label: string
  /** First year in the period; null for the open-ended first period. */
  from: number | null
  /** First year after the period; null for the open-ended last period. */
  until: number | null
}

export interface PeriodColumn {
  period: Period
  works: Artwork[]
}

/** Periods split at the given years, which must be in ascending order. */
export function makePeriods(boundaries: number[]): Period[] {
  const periods: Period[] = [
    { label: `Before ${boundaries[0]}`, from: null, until: boundaries[0] },
  ]
  boundaries.forEach((from, index) => {
    const until = boundaries[index + 1] ?? null
    periods.push({
      label: until === null ? `${from} and later` : `${from}–${until - 1}`,
      from,
      until,
    })
  })
  return periods
}

function holds(period: Period, year: number): boolean {
  return (
    (period.from === null || year >= period.from) &&
    (period.until === null || year < period.until)
  )
}

/** Dated works in period columns, oldest first; undated works are counted. */
export function bucketWorks(
  works: Artwork[],
  periods: Period[],
): { columns: PeriodColumn[]; undated: number } {
  const dated = sortWorks(
    works.filter((work) => work.year !== null),
    'year',
    'asc',
  )
  const columns = periods.map((period) => ({
    period,
    works: dated.filter((work) => holds(period, work.year as number)),
  }))
  return { columns, undated: works.length - dated.length }
}
